a, b, c, d, e, f, x = map(int, input().split())
xbk = x
y, z = 0, 0

# Calculate distance traveled by Takahashi
while x > 0:
    if x >= a + c:
        y += a * b
        x -= a + c
    else:
        y += x * b
        x = 0

# Calculate distance traveled by Aoki
while xbk > 0:
    if xbk >= d + f:
        z += d * e
        xbk -= d + f
    else:
        z += xbk * e
        xbk = 0

print("Takahashi" if y > z else "Aoki" if y < z else "Draw")
